var userAgentIsMobile = false;
var userAgentIsAndroid = false;
var subFormFieldCount = 0;
var cameraFacingMode = 'user';
let videoStream;

jQuery(document).ready(function() {
	var userAgent = navigator.userAgent || navigator.vendor || window.opera;

	/* For mobile devices need to use a button to initialise camera as its not initialised on page load*/
	if (/Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(userAgent)) {
		userAgentIsMobile = true;
	}

	/* Check if useragent is android as we need to show camera switch button for android devices*/
	if (/android/i.test(userAgent)) {
		userAgentIsAndroid = true;
	}

	/* Initialise camera on page load by clicking a hidden button - the button is used in case of mobile devices as we cant activate camera on page load on mobile devices*/
	jQuery.each(jQuery(document).find(jQuery("input[onClick^='set_camera(']")), function(key, value) {
		if (jQuery('#' + jQuery(value).attr('id').replace('take_another', '_hasvalue')).val() == '0') {
			jQuery(value).click();
		}
	});

	/* Hide button to capture image on mobile device as this is done via mobile interface*/
	jQuery.each(jQuery(document).find(jQuery("input[onClick^='take_snapshot(']")), function(key, value) {
		if (userAgentIsMobile) {
			document.getElementById(jQuery(value).attr('id')).style = 'display:none;';
		}
	});

	/* Hide switch camera button is useragent is not android */
	jQuery.each(jQuery(document).find(jQuery("input[onClick^='switch_camera(']")), function(key, value) {
		if (userAgentIsAndroid === false) {
			document.getElementById(jQuery(value).attr('id')).style = 'display:none;';
		}
	});

	/* Update the options of related field for new record of subform */
	jQuery(document).on('subform-row-add', function(event, row) {
		subFormFieldCount = jQuery(event.detail.row).attr('data-group').replace(jQuery(event.detail.row).attr('data-base-name'), "");
		var likeName = 'jform_' + jQuery(event.detail.row).attr('data-base-name') + '__' + jQuery(event.detail.row).attr('data-group').substring(0, jQuery(event.detail.row).attr('data-group').length - 7);

		/* Update the id of elements used in field when a new group of field is added for subform */
		jQuery.each(jQuery(event.detail.row).find(jQuery("input[id^='" + likeName + "']")), function(key, value) {
			jQuery(value).attr('id', jQuery(value).attr('id').replace("X__", subFormFieldCount + '__'));
		});

		/* Update the id of elements used in field when a new group of field is added for subform */
		jQuery.each(jQuery(event.detail.row).find(jQuery("div[id^='" + likeName + "']")), function(key, value) {
			jQuery(value).attr('id', jQuery(value).attr('id').replace("X__", subFormFieldCount + '__'));
		});

		/* Initialise camera on page load by clicking a hidden button - the button is used in case of mobile devices as we cant activate camera on page load on mobile devices*/
		jQuery.each(jQuery(event.detail.row).find(jQuery("input[onClick^='set_camera(']")), function(key, value) {
			if (jQuery('#' + jQuery(value).attr('id').replace('take_another', '_hasvalue')).val() == '0') {
				jQuery(value).click();
			}
		});

		/* Update the id of elements used in field when a new group of field is added for subform */
		jQuery.each(jQuery(event.detail.row).find(jQuery("input[onClick^='set_camera(']")), function(key, value) {
			jQuery(value).attr('onClick', jQuery(value).attr('onClick').replace('X__', subFormFieldCount + '__'));
		});

		/* Update the id of elements used in field when a new group of field is added for subform */
		jQuery.each(jQuery(event.detail.row).find(jQuery("input[onClick^='take_snapshot(']")), function(key, value) {
			jQuery(value).attr('onClick', jQuery(value).attr('onClick').replace('X__', subFormFieldCount + '__'));
		});

		/* Update the id of elements used in field when a new group of field is added for subform */
		jQuery.each(jQuery(event.detail.row).find(jQuery("input[onClick^='switch_camera(']")), function(key, value) {
			jQuery(value).attr('onClick', jQuery(value).attr('onClick').replace('X__', subFormFieldCount + '__'));

			if (userAgentIsAndroid == false)
			{
				document.getElementById(jQuery(value).attr('id')).style = 'display:none;';
			}
		});

		/* Update the id of elements used in field when a new group of field is added for subform */
		jQuery.each(jQuery(event.detail.row).find(jQuery("input[onClick^='switch_camera(']")), function(key, value) {
			jQuery(value).attr('onClick', jQuery(value).attr('onClick').replace('X__', subFormFieldCount + '__'));
		});

		/* Update the id of elements used in field when a new group of field is added for subform */
		jQuery.each(jQuery(event.detail.row).find(jQuery("input[onClick^='use_snapshot(']")), function(key, value) {
			jQuery(value).attr('onClick', jQuery(value).attr('onClick').replace('X__', subFormFieldCount + '__'));
		});

		/* Hide button to capture image on mobile device as this is done via mobile interface*/
		jQuery.each(jQuery(event.detail.row).find(jQuery("input[onClick^='take_snapshot(']")), function(key, value) {
			if (userAgentIsMobile) {
				document.getElementById(jQuery(value).attr('id')).style = 'display:none;';
			}
		});
	});
});

/* Method to take snapshot - used for non mobile devices*/
function take_snapshot(thisId) {
	var result = Webcam.snap(function(data_uri) {
		document.getElementById(thisId + '_capture_img').style = 'display:none';
		jQuery("#"+thisId + '_captured_img').attr('style', 'width:'+document.getElementById(thisId + '__camera_width').value+'px;height:'+document.getElementById(thisId + '__camera_height').value+'px;');
		jQuery('#' + thisId + '_captured_img').find("img").attr("src", data_uri);
		jQuery('#' + thisId).val(jQuery('#' + thisId + '_captured_img').find("img").attr("src")).trigger('change');
		document.getElementById(thisId + '_take_snapshot').style = 'display:none;';
		document.getElementById(thisId + '_switch_camera').style = 'display:none;';
		document.getElementById(thisId + '_take_another').style = '';
	});
}

/* Method to take snapshot - used for mobile devices*/
function use_snapshot(thisId) {
	var result = Webcam.snap(function(data_uri) {
		document.getElementById(thisId + '_capture_img').style = 'display:none';
		jQuery("#"+thisId + '_captured_img').attr('style', 'width:'+document.getElementById(thisId + '__camera_width').value+'px;height:'+document.getElementById(thisId + '__camera_height').value+'px;');
		jQuery('#' + thisId + '_captured_img').find("img").attr("src", data_uri);
		Webcam.reset();

		if (userAgentIsMobile) {
			document.getElementById(thisId + '_use').style = 'display:none;';
		}

		jQuery('#' + thisId).val(jQuery('#' + thisId + '_captured_img').find("img").attr("src")).trigger('change');

		document.getElementById(thisId + '_take_snapshot').style = 'display:none;';
		document.getElementById(thisId + '_switch_camera').style = 'display:none;';
		document.getElementById(thisId + '_take_another').style = '';
	});

}

/* Method to initialise and re-initialise camera - used for non mobile devices*/
function set_camera(thisId) {
	var userAgent = navigator.userAgent || navigator.vendor || window.opera;

	thisId = thisId.replace('X__', subFormFieldCount + '__');
	document.getElementById(thisId + '_capture_img').style = '';
	document.getElementById(thisId + '_captured_img').src = '';
	jQuery('#' + thisId + '_captured_img').find("img").attr("src", '');
	document.getElementById(thisId + '_captured_img').style = 'display:none';
	document.getElementById(thisId + '_take_another').style = 'display:none;';
	document.getElementById(thisId + '_take_snapshot').style = '';
	document.getElementById(thisId + '_use').style = 'display:none;';
	
	var captureImage = document.getElementById(thisId + '_captured_img');
	var enableCameraElement = document.getElementById(thisId + '_enable_camera');
	var disableCameraElement = document.getElementById(thisId + '_disable_camera');

    // Check if the elements exist before modifying their styles
    if (enableCameraElement && disableCameraElement) {
    	enableCameraElement.style.display = 'none';
    	disableCameraElement.style.display = '';
    	disableCameraElement.style.marginTop = '12px';
    }
    else if (captureImage && !disableCameraElement)
    {
		jQuery('#' + thisId + '_take_snapshot').after(
		  '<input type="button"style="margin-top: 12px;" id="' + thisId + '_disable_camera" value="disable camera" onClick="disableCamera(\'' + thisId + '\')">'
		);
		jQuery('#' + thisId + '_take_snapshot').after(
		  '<input type="button" style="display:none;" id="' + thisId + '_enable_camera" value="enable camera" onClick="enableCamera(\'' + thisId + '\')">'
		);
    }
	// Check if the browser supports the necessary API
	if (navigator.mediaDevices && navigator.mediaDevices.getUserMedia) {
    // Check if camera access is granted
    navigator.mediaDevices.getUserMedia({ video: true })
    .then(function(stream) {

    })
    .catch(function(error) {
    	document.getElementById(thisId + '_enable_camera').style = 'display:;';
    	document.getElementById(thisId + '_disable_camera').style = 'display:none;';
    	document.getElementById(thisId + '_take_snapshot').style = 'display:none';
    	document.getElementById(thisId + '_switch_camera').style = 'display:none;';
		document.getElementById(thisId + '_use').style = 'display:none;';
    	

if(!/iPhone|iPad|iPod/i.test(userAgent)){
		setTimeout(function(){
    			var innerDiv =  jQuery('#' + thisId + '_capture_img').find('div');

    // Append the image to the inner div

    if (innerDiv.length) {
    	var siteUrl = window.location.origin;
    	var elementStyle = document.getElementById(thisId + '_capture_img').style.cssText;
    	jQuery('#' + thisId + '_capture_img').removeAttr('style');
    	jQuery('#' + thisId + '_capture_img').find('div').empty();
    	jQuery('#' + thisId + '_capture_img').find('div').append('<img class="diableimage"src="' + siteUrl + '/media/com_dpe/images/disabledcamera.jpeg" alt="Description of image" style="margin-left:38%;width:100px;height:100px;">');  }
    	jQuery('#' + thisId + '_capture_img').find('div').append('<p class="diableimage" style="margin-left: 37%;">Camera is disabled</p>')
    	
    	var videoElement = jQuery('video');
    	videoElement.removeAttr('style');
    	videoElement.css('margin-top', '-25%');
    },1000)
}
if(/iPhone|iPad|iPod/i.test(userAgent)){

	document.getElementById(thisId + '_enable_camera').style = 'display:none;';
	document.getElementById(thisId + '_use').style = 'display:;';
	    document.getElementById(thisId + '_disable_camera').style = 'display:none;';

}

    });
} 
else {
	console.log('getUserMedia is not supported by this browser.');
}


if (userAgentIsMobile) {
	document.getElementById(thisId + '_take_snapshot').style = 'display:none;';
	document.getElementById(thisId + '_use').style = '';
}

if (userAgentIsAndroid)
{
	document.getElementById(thisId + '_switch_camera').style = '';

}

/* WebcamJs code to initialise camera - used for mobile devices*/
Webcam.set({
	width: document.getElementById(thisId + '__camera_width').value,
	height: document.getElementById(thisId + '__camera_height').value,
	dest_width: document.getElementById(thisId + '__camera_width').value*2,
	dest_height: document.getElementById(thisId + '__camera_height').value*2,
	flip_horiz: true,
	image_format: 'jpeg',
	jpeg_quality: 100
});

/* WebcamJs code to attach camera outupt to a div on the page*/
Webcam.attach('#' + thisId + '_capture_img');
}

/* Method to switch camera mode - used for android mobile devices only*/
function switch_camera(thisId) {
	if (userAgentIsAndroid)
	{
		cameraFacingMode = (cameraFacingMode == 'user') ? 'environment' : 'user';

		Webcam.reset();

		Webcam.set({
			width: document.getElementById(thisId + '__camera_width').value,
			height: document.getElementById(thisId + '__camera_height').value,
			dest_width: document.getElementById(thisId + '__camera_width').value*2,
			dest_height: document.getElementById(thisId + '__camera_height').value*2,
			flip_horiz: true,
			image_format: 'jpeg',
			jpeg_quality: 100,
			constraints: {
				facingMode: cameraFacingMode
			}
		});

		/* WebcamJs code to attach camera outupt to a div on the page*/
		Webcam.attach('#' + thisId + '_capture_img');
	}
}


function enableCamera(thisId){

	var userAgent = navigator.userAgent || navigator.vendor || window.opera;
	var hiddenInputIds = [];
	if (navigator.permissions) {
		navigator.permissions.query({ name: 'camera' })
		.then(function(permissionStatus) { 
                  console.log('Camera permission status:', permissionStatus.state);
                if ((permissionStatus.state == 'denied')){
                	alert("Please enable camera permissions in your browser.");
                }else if(userAgentIsMobile && permissionStatus.state == 'granted'){
                	alert("Attempting to enable the camera. If unsuccessful, please manually enable the camera permission in your browser.");
                }

            })
		.catch(function(error) {
			console.error('Error checking camera permission:', error);
			alert("Please enable camera permissions in your browser.");
		});
	} else {
		alert("Please enable camera permissions in your browser.");
	}
	
	if(/iPad|iPhone|iPod/.test(navigator.userAgent) && !window.MSStream){               	   
	       
      alert("Attempting to enable the camera. If unsuccessful, please manually enable the camera permission in your browser.");
  				 
  }

        // Iterate over each video element
        jQuery('video').each(function() {
            // Find the closest parent with the class "controls"
            var controlsDiv =jQuery(this).closest('.controls');
            
            // Find the first hidden input inside this controls div
            var firstHiddenInput = controlsDiv.find('input[type="hidden"]').first();
            
            // Get the ID of the first hidden input and add it to the array
            var hiddenInputId = firstHiddenInput.attr('id');
            if (hiddenInputId) {
            	set_camera(hiddenInputId);
            	hiddenInputIds.push(hiddenInputId);
            }
        });
    }

    function disableCamera(thisId) {
    	const videoElements = document.querySelectorAll('video');

    // Loop through each video element
    videoElements.forEach(function(videoElement) {
        // If the video element has a stream, stop it
        if (videoElement.srcObject) {
        	let stream = videoElement.srcObject;
        	let tracks = stream.getTracks();

            // Stop all tracks in the stream (video and/or audio)
            tracks.forEach(track => track.stop());
            
            // Clear the video element's source
            videoElement.srcObject = null;
        }
    });
    var hiddenInputIds = [];

        // Iterate over each video element
        jQuery('video').each(function() {
            // Find the closest parent with the class "controls"
            var controlsDiv =jQuery(this).closest('.controls');
            
            // Find the first hidden input inside this controls div
            var firstHiddenInput = controlsDiv.find('input[type="hidden"]').first();
            
            // Get the ID of the first hidden input and add it to the array
            var hiddenInputId = firstHiddenInput.attr('id');
            if (hiddenInputId) {
            	document.getElementById(hiddenInputId + '_enable_camera').style.display = '';
            	document.getElementById(hiddenInputId + '_captured_img').style.display = 'none';
            	document.getElementById(hiddenInputId + '_disable_camera').style.display = 'none';
            	document.getElementById(hiddenInputId + '_take_snapshot').style.display = 'none';
		        document.getElementById(hiddenInputId + '_switch_camera').style = 'display:none;';
		        document.getElementById(hiddenInputId + '_use').style = 'display:none;';
		       
            }
            setTimeout(function(){
            	var innerDiv =  jQuery('#' + hiddenInputId + '_capture_img').find('div');

		    // Append the image to the inner div
		    if (innerDiv.length) {
		    	var siteUrl = window.location.origin;
		    	var elementStyle = document.getElementById(hiddenInputId + '_capture_img').style.cssText;
		    	jQuery('#' + hiddenInputId + '_capture_img').removeAttr('style');
		    	jQuery('#' + hiddenInputId + '_capture_img').find('div').empty();
		    	jQuery('#' + hiddenInputId + '_capture_img').find('div').append('<img class="diableimage"src="' + siteUrl + '/media/com_dpe/images/disabledcamera.jpeg" alt="Description of image" style="margin-left:38%;width:100px;height:100px;">');  }
		    	jQuery('#' + hiddenInputId + '_capture_img').find('div').append('<p class="diableimage" style="margin-left: 37%;">Camera is disabled</p>')
		    	var videoElement = jQuery('video');
		    	videoElement.removeAttr('style');
		    	videoElement.css('margin-top', '-25%');
		    },1000)	
        });
        jQuery('video')[0].srcObject = null;
        jQuery("video").css("display", "none");
    }
